/* P0-6: loaders check / list / verify, plus the fdl/index manifest.
 *
 * Moves the menu's chip/pair/stub validation (A7; audit6 C3) into C so
 * menu.sh and the app share one implementation. Everything here is offline:
 * no USB, no device, no writes. It reads the loader files it is asked about,
 * the exec stub, and fdl/index.
 *
 * fdl/index (format 1, text, generated by scripts/gen-fdl-index.sh):
 *   spdhost-fdl-index 1
 *   soc  NAME fdl1=0xA fdl2=0xB stub=0xC stub_alt=0xD
 *   file SHA256 KIND SOC ADDR RELPATH     KIND: fdl1|fdl2|cboot|stub, ADDR: 0x..|-
 *   pair SOC MODEL FDL1RELPATH FDL2RELPATH
 *   end
 * '#' lines and blank lines are ignored. RELPATH is relative to the index's
 * directory (the fdl/ folder), never absolute, never "..". The soc rows must
 * equal this build's own table (below): an index that disagrees with the
 * binary about where a chip's loaders go is refused, not trusted.
 */
#define _GNU_SOURCE
#include "loaders.h"
#include "sha256.h"

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#define LOADER_MAX_BYTES (16u << 20) /* FDLs and stubs are KiB; refuse anything absurd */

struct soc_row {
	const char *name;
	uint32_t fdl1, fdl2, stub, stub_alt;
};

/* Same numbers as menu.sh soc_profile and main.c exec_chip/exec_chip_fdl1. */
static const struct soc_row builtin_socs[] = {
	{ "ums9230", 0x65000800u, 0x9efffe00u, 0x65015f08u, 0x65015f48u },
	{ "ums512",  0x5500u,     0x9efffe00u, 0x3ee8u,     0x3f48u },
	{ "sc9863a", 0x5000u,     0x9efffe00u, 0x4ee8u,     0x4f48u },
};
#define NSOC (sizeof(builtin_socs) / sizeof(builtin_socs[0]))

struct idx_file {
	char sha[65];
	char kind[8];
	char soc[16];
	uint32_t addr; /* 0 = '-' */
	char *rel;
};

struct idx_pair {
	char soc[16];
	char *model;
	char *rel1, *rel2;
	const struct idx_file *f1, *f2;
};

struct index {
	char path[PATH_MAX];
	char dir[PATH_MAX]; /* realpath of the index's folder */
	struct idx_file *files;
	size_t nfiles;
	struct idx_pair *pairs;
	size_t npairs;
	int socs_seen[NSOC];
};

static const struct soc_row *soc_by_name(const char *n)
{
	size_t k;
	if (!n)
		return NULL;
	for (k = 0; k < NSOC; k++)
		if (!strcmp(builtin_socs[k].name, n))
			return &builtin_socs[k];
	return NULL;
}

/* The chip whose exec stub sits at EA (exact stub/stub_alt), or NULL. */
static const struct soc_row *soc_by_stub(uint32_t ea)
{
	size_t k;
	for (k = 0; k < NSOC; k++)
		if (builtin_socs[k].stub == ea || builtin_socs[k].stub_alt == ea)
			return &builtin_socs[k];
	return NULL;
}

static int parse_u32(const char *s, uint32_t *out)
{
	char *end = NULL;
	unsigned long long v;
	if (!s || !*s || *s == '-' || *s == '+')
		return -1;
	errno = 0;
	v = strtoull(s, &end, 0);
	if (errno || !end || *end || v > 0xffffffffull)
		return -1;
	*out = (uint32_t)v;
	return 0;
}

static int is_sha256_hex(const char *s)
{
	size_t k;
	for (k = 0; s[k]; k++)
		if (!((s[k] >= '0' && s[k] <= '9') || (s[k] >= 'a' && s[k] <= 'f')))
			return 0;
	return k == 64;
}

static int rel_ok(const char *r)
{
	const char *p = r;
	if (!*r || *r == '/')
		return 0;
	while (*p) {
		const char *e = strchr(p, '/');
		size_t n = e ? (size_t)(e - p) : strlen(p);
		if (n == 0 || (n == 1 && p[0] == '.') || (n == 2 && p[0] == '.' && p[1] == '.'))
			return 0;
		p += n;
		if (*p == '/')
			p++;
	}
	return 1;
}

static void index_free(struct index *ix)
{
	size_t k;
	for (k = 0; k < ix->nfiles; k++)
		free(ix->files[k].rel);
	for (k = 0; k < ix->npairs; k++) {
		free(ix->pairs[k].model);
		free(ix->pairs[k].rel1);
		free(ix->pairs[k].rel2);
	}
	free(ix->files);
	free(ix->pairs);
	memset(ix, 0, sizeof(*ix));
}

static const struct idx_file *index_file_by_rel(const struct index *ix, const char *rel)
{
	size_t k;
	for (k = 0; k < ix->nfiles; k++)
		if (!strcmp(ix->files[k].rel, rel))
			return &ix->files[k];
	return NULL;
}

/* Load and validate. Returns 0, or -1 with a reason in ERR. */
static int index_load(struct index *ix, const char *path, char *err, size_t errsz)
{
	FILE *f;
	char line[2048];
	int lineno = 0, have_magic = 0, have_end = 0;
	size_t k;
	char *slash;
	char tmp[PATH_MAX];

	memset(ix, 0, sizeof(*ix));
	snprintf(ix->path, sizeof(ix->path), "%s", path);
	f = fopen(path, "r");
	if (!f) {
		snprintf(err, errsz, "cannot open %s: %s", path, strerror(errno));
		return -1;
	}
	snprintf(tmp, sizeof(tmp), "%s", path);
	slash = strrchr(tmp, '/');
	if (slash)
		*slash = 0;
	else
		snprintf(tmp, sizeof(tmp), ".");
	if (!realpath(tmp, ix->dir)) {
		snprintf(err, errsz, "cannot resolve %.900s: %s", tmp, strerror(errno));
		fclose(f);
		return -1;
	}
#define BAD(...) do { snprintf(err, errsz, __VA_ARGS__); fclose(f); index_free(ix); return -1; } while (0)
	while (fgets(line, sizeof(line), f)) {
		char *tok[8];
		int nt = 0;
		char *p, *save = NULL;
		size_t len = strlen(line);
		lineno++;
		if (len && line[len - 1] != '\n' && !feof(f))
			BAD("%s:%d: line too long", path, lineno);
		while (len && (line[len - 1] == '\n' || line[len - 1] == '\r'))
			line[--len] = 0;
		if (!len || line[0] == '#')
			continue;
		if (have_end)
			BAD("%s:%d: text after end", path, lineno);
		for (p = strtok_r(line, " \t", &save); p && nt < 8; p = strtok_r(NULL, " \t", &save))
			tok[nt++] = p;
		if (p)
			BAD("%s:%d: too many fields", path, lineno);
		if (!have_magic) {
			if (nt != 2 || strcmp(tok[0], "spdhost-fdl-index") || strcmp(tok[1], "1"))
				BAD("%s: not an spdhost fdl index (format 1)", path);
			have_magic = 1;
			continue;
		}
		if (!strcmp(tok[0], "end") && nt == 1) {
			have_end = 1;
		} else if (!strcmp(tok[0], "soc") && nt == 6) {
			const struct soc_row *s = soc_by_name(tok[1]);
			uint32_t v[4];
			const char *keys[4] = { "fdl1=", "fdl2=", "stub=", "stub_alt=" };
			int j;
			if (!s)
				BAD("%s:%d: unknown chip %s", path, lineno, tok[1]);
			for (j = 0; j < 4; j++) {
				size_t kl = strlen(keys[j]);
				if (strncmp(tok[2 + j], keys[j], kl) || parse_u32(tok[2 + j] + kl, &v[j]))
					BAD("%s:%d: bad field %s", path, lineno, tok[2 + j]);
			}
			if (v[0] != s->fdl1 || v[1] != s->fdl2 || v[2] != s->stub || v[3] != s->stub_alt)
				BAD("%s:%d: %s addresses disagree with this spdhost build", path, lineno, s->name);
			ix->socs_seen[s - builtin_socs] = 1;
		} else if (!strcmp(tok[0], "file") && nt == 6) {
			struct idx_file *nf;
			uint32_t a = 0;
			if (!is_sha256_hex(tok[1]))
				BAD("%s:%d: bad sha256", path, lineno);
			if (strcmp(tok[2], "fdl1") && strcmp(tok[2], "fdl2") && strcmp(tok[2], "cboot") &&
				strcmp(tok[2], "stub"))
				BAD("%s:%d: bad kind %s", path, lineno, tok[2]);
			if (!soc_by_name(tok[3]))
				BAD("%s:%d: unknown chip %s", path, lineno, tok[3]);
			if (strcmp(tok[4], "-") && parse_u32(tok[4], &a))
				BAD("%s:%d: bad address %s", path, lineno, tok[4]);
			if (!rel_ok(tok[5]))
				BAD("%s:%d: bad path %s", path, lineno, tok[5]);
			{
				const struct soc_row *s = soc_by_name(tok[3]);
				int okaddr = !strcmp(tok[2], "fdl1") ? a == s->fdl1 :
					!strcmp(tok[2], "fdl2") ? a == s->fdl2 :
					!strcmp(tok[2], "stub") ? (a == s->stub || a == s->stub_alt) : a == 0;
				if (!okaddr)
					BAD("%s:%d: %s address %s is not %s's", path, lineno, tok[2], tok[4], s->name);
			}
			if (index_file_by_rel(ix, tok[5]))
				BAD("%s:%d: %s listed twice", path, lineno, tok[5]);
			nf = realloc(ix->files, (ix->nfiles + 1) * sizeof(*nf));
			if (!nf)
				BAD("out of memory");
			ix->files = nf;
			nf = &ix->files[ix->nfiles];
			memset(nf, 0, sizeof(*nf));
			memcpy(nf->sha, tok[1], 65);
			snprintf(nf->kind, sizeof(nf->kind), "%s", tok[2]);
			snprintf(nf->soc, sizeof(nf->soc), "%s", tok[3]);
			nf->addr = a;
			nf->rel = strdup(tok[5]);
			if (!nf->rel)
				BAD("out of memory");
			ix->nfiles++;
		} else if (!strcmp(tok[0], "pair") && nt == 5) {
			struct idx_pair *np;
			if (!soc_by_name(tok[1]))
				BAD("%s:%d: unknown chip %s", path, lineno, tok[1]);
			if (!rel_ok(tok[2]) || !rel_ok(tok[3]) || !rel_ok(tok[4]))
				BAD("%s:%d: bad pair field", path, lineno);
			np = realloc(ix->pairs, (ix->npairs + 1) * sizeof(*np));
			if (!np)
				BAD("out of memory");
			ix->pairs = np;
			np = &ix->pairs[ix->npairs];
			memset(np, 0, sizeof(*np));
			snprintf(np->soc, sizeof(np->soc), "%s", tok[1]);
			np->model = strdup(tok[2]);
			np->rel1 = strdup(tok[3]);
			np->rel2 = strdup(tok[4]);
			ix->npairs++;
			if (!np->model || !np->rel1 || !np->rel2)
				BAD("out of memory");
		} else {
			BAD("%s:%d: unknown line", path, lineno);
		}
	}
	if (!have_magic)
		BAD("%s: empty index", path);
	if (!have_end)
		BAD("%s: no end line (truncated?)", path);
	fclose(f);
#undef BAD
	/* Pairs point at fdl1/fdl2 rows of their own chip. */
	for (k = 0; k < ix->npairs; k++) {
		struct idx_pair *p = &ix->pairs[k];
		p->f1 = index_file_by_rel(ix, p->rel1);
		p->f2 = index_file_by_rel(ix, p->rel2);
		if (!p->f1 || !p->f2 || strcmp(p->f1->kind, "fdl1") || strcmp(p->f2->kind, "fdl2") ||
			strcmp(p->f1->soc, p->soc) || strcmp(p->f2->soc, p->soc)) {
			snprintf(err, errsz, "%s: pair %s %s does not name an fdl1+fdl2 of that chip",
				path, p->soc, p->model);
			index_free(ix);
			return -1;
		}
	}
	return 0;
}

/* fdl/index next to the binary (package root), one level up, then ./fdl. */
static const char *find_index(const char *self_path)
{
	static char out[PATH_MAX];
	const char *rel[] = { "%s/fdl/index", "%s/../fdl/index", NULL };
	const char *slash = self_path ? strrchr(self_path, '/') : NULL;
	int k;
	if (slash) {
		char dir[PATH_MAX];
		size_t n = (size_t)(slash - self_path);
		if (n >= sizeof(dir))
			n = sizeof(dir) - 1;
		memcpy(dir, self_path, n);
		dir[n] = 0;
		for (k = 0; rel[k]; k++) {
			snprintf(out, sizeof(out), rel[k], dir);
			if (access(out, R_OK) == 0)
				return out;
		}
	}
	snprintf(out, sizeof(out), "fdl/index");
	if (access(out, R_OK) == 0)
		return out;
	return NULL;
}

/* sha256 of a regular file, at most LOADER_MAX_BYTES. */
static int file_sha(const char *path, char out[65], char *err, size_t errsz)
{
	int fd;
	struct stat st;
	struct sha256_ctx c;
	uint8_t buf[65536];
	ssize_t n;
	fd = open(path, O_RDONLY | O_CLOEXEC);
	if (fd < 0) {
		snprintf(err, errsz, "cannot open %s: %s", path, strerror(errno));
		return -1;
	}
	if (fstat(fd, &st) || !S_ISREG(st.st_mode)) {
		snprintf(err, errsz, "%s is not a regular file", path);
		close(fd);
		return -1;
	}
	if (st.st_size == 0 || (uint64_t)st.st_size > LOADER_MAX_BYTES) {
		snprintf(err, errsz, "%s is %s", path, st.st_size ? "too large for a loader" : "empty");
		close(fd);
		return -1;
	}
	sha256_init(&c);
	while ((n = read(fd, buf, sizeof(buf))) > 0)
		sha256_update(&c, buf, (size_t)n);
	if (n < 0) {
		snprintf(err, errsz, "read %s: %s", path, strerror(errno));
		close(fd);
		return -1;
	}
	close(fd);
	sha256_final_hex(&c, out);
	return 0;
}

/* The chip a path names by its shape .../fdl/<soc>/... (menu.sh path_soc),
 * or relative to the index folder. NULL when it names none. */
static const char *path_soc(const char *path, const char *real, const struct index *ix)
{
	static char seg[16];
	const char *p = NULL, *q;
	size_t n;
	if (ix && ix->dir[0] && real) {
		size_t dl = strlen(ix->dir);
		if (!strncmp(real, ix->dir, dl) && real[dl] == '/')
			p = real + dl + 1;
	}
	if (!p) {
		q = strstr(path, "/fdl/");
		if (q)
			p = q + 5;
		else if (!strncmp(path, "fdl/", 4))
			p = path + 4;
	}
	if (!p)
		return NULL;
	q = strchr(p, '/');
	n = q ? (size_t)(q - p) : strlen(p);
	if (!q || n >= sizeof(seg))
		return NULL;
	memcpy(seg, p, n);
	seg[n] = 0;
	return soc_by_name(seg) ? seg : NULL;
}

struct ident {
	const char *path;
	char real[PATH_MAX];
	char sha[65];
	char soc[16];      /* "" = unknown */
	const char *id;    /* index | path | none */
	const char *rel;   /* path relative to the index folder, or NULL */
	const struct idx_file *row; /* index row by sha, preferring same path */
	char kinds[64];    /* kinds this sha is shipped as */
};

/* Fills ID. Returns 0, or -1 with a refusal reason in ERR. */
static int identify(struct ident *id, const char *path, const char *want_kind,
	const struct index *ix, char *err, size_t errsz)
{
	size_t k;
	const char *socs[2] = { NULL, NULL };
	const struct idx_file *byrel = NULL;
	const char *rel = NULL;
	memset(id, 0, sizeof(*id));
	id->path = path;
	if (file_sha(path, id->sha, err, errsz))
		return -1;
	if (!realpath(path, id->real))
		snprintf(id->real, sizeof(id->real), "%s", path);
	if (ix && ix->dir[0]) {
		size_t dl = strlen(ix->dir);
		if (!strncmp(id->real, ix->dir, dl) && id->real[dl] == '/') {
			rel = id->real + dl + 1;
			byrel = index_file_by_rel(ix, rel);
			id->rel = rel;
		}
	}
	/* A file at an indexed path must carry the indexed bytes. */
	if (byrel && strcmp(byrel->sha, id->sha)) {
		snprintf(err, errsz, "%s does not match fdl/index (sha256 %.12s, index says %.12s): "
			"modified or corrupt loader", path, id->sha, byrel->sha);
		return -1;
	}
	if (ix) {
		for (k = 0; k < ix->nfiles; k++) {
			const struct idx_file *r = &ix->files[k];
			if (strcmp(r->sha, id->sha))
				continue;
			if (!id->row || r == byrel)
				id->row = r;
			if (!strstr(id->kinds, r->kind)) {
				size_t l = strlen(id->kinds);
				snprintf(id->kinds + l, sizeof(id->kinds) - l, "%s%s", l ? "," : "", r->kind);
			}
			if (!socs[0] || !strcmp(socs[0], r->soc))
				socs[0] = r->soc;
			else
				socs[1] = r->soc;
		}
	}
	if (id->row) {
		if (socs[1]) {
			snprintf(err, errsz, "%s is shipped for two chips (%s and %s); cannot tell which",
				path, socs[0], socs[1]);
			return -1;
		}
		if (!strstr(id->kinds, want_kind)) {
			snprintf(err, errsz, "%s is a shipped %s, not an %s", path, id->kinds, want_kind);
			return -1;
		}
		snprintf(id->soc, sizeof(id->soc), "%s", socs[0]);
		id->id = "index";
		return 0;
	}
	{
		const char *ps = path_soc(path, id->real, ix);
		if (ps) {
			snprintf(id->soc, sizeof(id->soc), "%.15s", ps);
			id->id = "path";
		} else {
			id->id = "none";
		}
	}
	return 0;
}

static void kv(const char *k, const char *fmt, ...)
{
	va_list ap;
	printf("%s=", k);
	va_start(ap, fmt);
	vprintf(fmt, ap);
	va_end(ap);
	putchar('\n');
}

static int loaders_usage(void)
{
	fprintf(stderr,
		"loaders check [--index FILE] [--soc SOC|none] [--exec ADDR|0] [--stub FILE]\n"
		"              FDL1 FDL1_ADDR FDL2 FDL2_ADDR\n"
		"loaders list [--index FILE]\n"
		"loaders verify [--index FILE]\n");
	return 2;
}

static int finish(int refused, const char *reason)
{
	kv("verdict", "%s", refused ? "refuse" : "ok");
	if (refused)
		kv("reason", "%s", reason);
	printf("end\n");
	fflush(stdout);
	if (refused)
		fprintf(stderr, "loaders: refusing: %s\n", reason);
	return refused ? 1 : 0;
}

static int cmd_check(int argc, char **argv, const char *self_path)
{
	const char *index_path = NULL, *soc_opt = NULL, *exec_opt = NULL, *stub_opt = NULL;
	const char *pos[4];
	int npos = 0, i, have_ix = 0, endopts = 0;
	struct index ix;
	char err[1024] = "", reason[1024] = "";
	uint32_t a1, a2, ea = 0;
	struct ident i1, i2, is;
	const struct soc_row *soc = NULL, *stub_soc = NULL;
	char soc_name[16] = "";
	char stub_path[PATH_MAX] = "";
	const char *pair = "unknown";
	char pairbuf[256];
	int nwarn = 0;
	char warns[4][512];

	for (i = 1; i < argc; i++) {
		const char **slot;
		if (!endopts && !strcmp(argv[i], "--")) {
			endopts = 1;
			continue;
		}
		slot = endopts ? NULL : !strcmp(argv[i], "--index") ? &index_path :
			!strcmp(argv[i], "--soc") ? &soc_opt :
			!strcmp(argv[i], "--exec") ? &exec_opt :
			!strcmp(argv[i], "--stub") ? &stub_opt : NULL;
		if (slot) {
			if (i + 1 >= argc || *slot)
				return loaders_usage();
			*slot = argv[++i];
		} else if (!endopts && argv[i][0] == '-' && argv[i][1] == '-') {
			return loaders_usage();
		} else if (npos < 4) {
			pos[npos++] = argv[i];
		} else {
			return loaders_usage();
		}
	}
	if (npos != 4 || parse_u32(pos[1], &a1) || parse_u32(pos[3], &a2))
		return loaders_usage();
	if (soc_opt && strcmp(soc_opt, "none") && !soc_by_name(soc_opt)) {
		fprintf(stderr, "loaders: --soc %s: not a chip this build knows (ums9230, ums512, sc9863a, none)\n",
			soc_opt);
		return 2;
	}
	if (exec_opt && parse_u32(exec_opt, &ea)) {
		if (strcmp(exec_opt, "off"))
			return loaders_usage();
		ea = 0;
	}
	if (stub_opt && (!exec_opt || !ea))
		return loaders_usage();

	printf("loaders_format=1\n");
	if (!index_path)
		index_path = find_index(self_path);
	if (index_path) {
		if (index_load(&ix, index_path, err, sizeof(err))) {
			kv("index", "%s", index_path);
			snprintf(reason, sizeof(reason), "bad fdl/index: %s", err);
			return finish(1, reason);
		}
		have_ix = 1;
		kv("index", "%s", index_path);
	} else {
		memset(&ix, 0, sizeof(ix));
		kv("index", "none");
	}
#define REFUSE(...) do { snprintf(reason, sizeof(reason), __VA_ARGS__); goto out; } while (0)
	if (identify(&i1, pos[0], "fdl1", have_ix ? &ix : NULL, err, sizeof(err)))
		REFUSE("FDL1: %s", err);
	kv("fdl1", "%s", pos[0]);
	kv("fdl1_sha256", "%s", i1.sha);
	kv("fdl1_soc", "%s", i1.soc[0] ? i1.soc : "unknown");
	kv("fdl1_id", "%s", i1.id);
	if (identify(&i2, pos[2], "fdl2", have_ix ? &ix : NULL, err, sizeof(err)))
		REFUSE("FDL2: %s", err);
	kv("fdl2", "%s", pos[2]);
	kv("fdl2_sha256", "%s", i2.sha);
	kv("fdl2_soc", "%s", i2.soc[0] ? i2.soc : "unknown");
	kv("fdl2_id", "%s", i2.id);

	/* Chip: two loaders of two chips are not a pair, whatever else is said. */
	if (i1.soc[0] && i2.soc[0] && strcmp(i1.soc, i2.soc))
		REFUSE("not a pair: FDL1 is %s's and FDL2 is %s's", i1.soc, i2.soc);
	{
		const char *ps = i1.soc[0] ? i1.soc : i2.soc[0] ? i2.soc : NULL;
		if (soc_opt && !strcmp(soc_opt, "none")) {
			if (ps)
				REFUSE("the loaders are %s's but the chip was given as none (another chip)", ps);
		} else if (soc_opt) {
			if (ps && strcmp(ps, soc_opt))
				REFUSE("the loaders are %s's but the chip was given as %s", ps, soc_opt);
			soc = soc_by_name(soc_opt);
		} else if (ps) {
			soc = soc_by_name(ps);
		}
	}
	if (soc)
		snprintf(soc_name, sizeof(soc_name), "%s", soc->name);
	kv("soc", "%s", soc ? soc->name : "none");

	/* Addresses are a function of the chip. */
	if (soc && a1 != soc->fdl1)
		REFUSE("FDL1 address 0x%x is not %s's (0x%x)", (unsigned)a1, soc->name, (unsigned)soc->fdl1);
	if (soc && a2 != soc->fdl2)
		REFUSE("FDL2 address 0x%x is not %s's (0x%x)", (unsigned)a2, soc->name, (unsigned)soc->fdl2);
	if (!soc && a2 != 0x9efffe00u && nwarn < 4)
		snprintf(warns[nwarn++], sizeof(warns[0]),
			"FDL2 address 0x%x is not 0x9efffe00, which every shipped chip uses", (unsigned)a2);
	kv("fdl1_addr", "0x%x", (unsigned)a1);
	kv("fdl2_addr", "0x%x", (unsigned)a2);

	/* Exec stub: explicit --exec wins (0 = none); else the chip's default;
	 * no chip, no stub (menu.sh L6/G3). */
	if (!exec_opt && soc)
		ea = soc->stub;
	if (ea) {
		stub_soc = soc_by_stub(ea);
		if (!stub_soc && !stub_opt)
			REFUSE("exec_addr 0x%x is no shipped chip's stub address (pass --stub FILE or --exec 0)",
				(unsigned)ea);
		if (stub_soc && soc && stub_soc != soc)
			REFUSE("exec_addr 0x%x is %s's stub but the loaders are %s's", (unsigned)ea,
				stub_soc->name, soc->name);
		/* M4: the stub jumps into its chip's FDL1 load address. */
		if (stub_soc && a1 != stub_soc->fdl1)
			REFUSE("exec stub 0x%x is the %s stub, which goes with FDL1 at 0x%x, not 0x%x",
				(unsigned)ea, stub_soc->name, (unsigned)stub_soc->fdl1, (unsigned)a1);
		if (stub_opt) {
			snprintf(stub_path, sizeof(stub_path), "%s", stub_opt);
		} else {
			/* The same name spdhost looks up: fdl/<chip>/custom_exec_no_verify_<hex>.bin,
			 * next to the index first. */
			if (have_ix) {
				snprintf(stub_path, sizeof(stub_path), "%.3900s/%s/custom_exec_no_verify_%x.bin",
					ix.dir, stub_soc->name, (unsigned)ea);
			}
			if (!stub_path[0] || access(stub_path, R_OK)) {
				const char *slash = self_path ? strrchr(self_path, '/') : NULL;
				int found = 0;
				if (slash) {
					const char *rel[] = { "%.*s/fdl/%s/custom_exec_no_verify_%x.bin",
						"%.*s/../fdl/%s/custom_exec_no_verify_%x.bin", NULL };
					int k;
					for (k = 0; rel[k] && !found; k++) {
						snprintf(stub_path, sizeof(stub_path), rel[k], (int)(slash - self_path),
							self_path, stub_soc->name, (unsigned)ea);
						found = access(stub_path, R_OK) == 0;
					}
				}
				if (!found)
					REFUSE("missing custom_exec_no_verify_%x.bin for exec_addr 0x%x (fdl/%s/)",
						(unsigned)ea, (unsigned)ea, stub_soc->name);
			}
		}
		if (identify(&is, stub_path, "stub", have_ix ? &ix : NULL, err, sizeof(err)))
			REFUSE("exec stub: %s", err);
		if (is.row) {
			if (stub_soc && strcmp(is.row->soc, stub_soc->name))
				REFUSE("exec stub %s is %s's, not %s's", stub_path, is.row->soc, stub_soc->name);
			if (is.row->addr != ea)
				REFUSE("exec stub %s is the 0x%x stub, not 0x%x", stub_path,
					(unsigned)is.row->addr, (unsigned)ea);
		} else if (stub_soc && is.soc[0] && strcmp(is.soc, stub_soc->name)) {
			REFUSE("exec stub %s is under fdl/%s/, not fdl/%s/", stub_path, is.soc, stub_soc->name);
		} else if (have_ix && nwarn < 4) {
			snprintf(warns[nwarn++], sizeof(warns[0]), "exec stub %s is not in fdl/index", stub_path);
		}
		kv("exec", "0x%x", (unsigned)ea);
		kv("stub", "%s", stub_path);
		kv("stub_sha256", "%s", is.sha);
		kv("stub_id", "%s", is.id);
	} else {
		kv("exec", "none");
	}

	/* Pair: both shipped and listed together, or a mix of two shipped models
	 * of one chip (allowed, but said out loud), or not shipped. */
	if (have_ix && i1.row && i2.row) {
		size_t k;
		pair = "mixed";
		/* The pair at these very paths first (two models can ship the same
		 * bytes: realme and tecno), then any pair with these bytes. */
		for (k = 0; k < ix.npairs && i1.rel && i2.rel; k++) {
			if (!strcmp(ix.pairs[k].rel1, i1.rel) && !strcmp(ix.pairs[k].rel2, i2.rel)) {
				snprintf(pairbuf, sizeof(pairbuf), "%s/%s", ix.pairs[k].soc, ix.pairs[k].model);
				pair = pairbuf;
				break;
			}
		}
		for (k = 0; k < ix.npairs && !strcmp(pair, "mixed"); k++) {
			if (!strcmp(ix.pairs[k].f1->sha, i1.sha) && !strcmp(ix.pairs[k].f2->sha, i2.sha)) {
				snprintf(pairbuf, sizeof(pairbuf), "%s/%s", ix.pairs[k].soc, ix.pairs[k].model);
				pair = pairbuf;
				break;
			}
		}
		if (!strcmp(pair, "mixed") && nwarn < 4)
			snprintf(warns[nwarn++], sizeof(warns[0]),
				"FDL1 and FDL2 are shipped loaders of different %s models, not one pair", soc_name);
	} else if (i1.row || i2.row) {
		pair = "partial";
		if (nwarn < 4)
			snprintf(warns[nwarn++], sizeof(warns[0]), "only one of FDL1/FDL2 is a shipped loader");
	}
	kv("pair", "%s", pair);
	for (i = 0; i < nwarn; i++)
		kv("warning", "%s", warns[i]);
#undef REFUSE
out:
	if (have_ix)
		index_free(&ix);
	return finish(reason[0] != 0, reason);
}

static int load_for_cmd(struct index *ix, int argc, char **argv, const char *self_path)
{
	const char *p = NULL;
	char err[1024];
	if (argc == 3 && !strcmp(argv[1], "--index"))
		p = argv[2];
	else if (argc != 1)
		return loaders_usage();
	if (!p)
		p = find_index(self_path);
	if (!p) {
		fprintf(stderr, "loaders: no fdl/index next to spdhost or in ./fdl (pass --index FILE)\n");
		return 1;
	}
	if (index_load(ix, p, err, sizeof(err))) {
		fprintf(stderr, "loaders: bad fdl/index: %s\n", err);
		return 1;
	}
	return 0;
}

static int cmd_list(int argc, char **argv, const char *self_path)
{
	struct index ix;
	size_t k;
	int rc = load_for_cmd(&ix, argc, argv, self_path);
	if (rc)
		return rc;
	printf("loaders_format=1\n");
	kv("index", "%s", ix.path);
	for (k = 0; k < NSOC; k++)
		printf("soc %s fdl1=0x%x fdl2=0x%x stub=0x%x stub_alt=0x%x\n", builtin_socs[k].name,
			(unsigned)builtin_socs[k].fdl1, (unsigned)builtin_socs[k].fdl2,
			(unsigned)builtin_socs[k].stub, (unsigned)builtin_socs[k].stub_alt);
	for (k = 0; k < ix.npairs; k++)
		printf("pair %s %s %s/%s %s/%s %s %s\n", ix.pairs[k].soc, ix.pairs[k].model, ix.dir,
			ix.pairs[k].rel1, ix.dir, ix.pairs[k].rel2, ix.pairs[k].f1->sha, ix.pairs[k].f2->sha);
	printf("end\n");
	index_free(&ix);
	return fflush(stdout) == 0 ? 0 : 1;
}

/* Every indexed file is present with its indexed bytes (an imported pack). */
static int cmd_verify(int argc, char **argv, const char *self_path)
{
	struct index ix;
	size_t k;
	int bad = 0;
	int rc = load_for_cmd(&ix, argc, argv, self_path);
	if (rc)
		return rc;
	printf("loaders_format=1\n");
	kv("index", "%s", ix.path);
	for (k = 0; k < ix.nfiles; k++) {
		char p[PATH_MAX * 2], sha[65], err[1024];
		snprintf(p, sizeof(p), "%s/%s", ix.dir, ix.files[k].rel);
		if (file_sha(p, sha, err, sizeof(err))) {
			printf("missing %s\n", ix.files[k].rel);
			bad++;
		} else if (strcmp(sha, ix.files[k].sha)) {
			printf("mismatch %s\n", ix.files[k].rel);
			bad++;
		}
	}
	kv("files", "%zu", ix.nfiles);
	kv("pairs", "%zu", ix.npairs);
	kv("bad", "%d", bad);
	kv("verdict", "%s", bad ? "refuse" : "ok");
	printf("end\n");
	index_free(&ix);
	fflush(stdout);
	return bad ? 1 : 0;
}

int spd_loaders_main(int argc, char **argv, const char *self_path)
{
	if (argc < 2)
		return loaders_usage();
	if (!strcmp(argv[1], "check"))
		return cmd_check(argc - 1, argv + 1, self_path);
	if (!strcmp(argv[1], "list"))
		return cmd_list(argc - 1, argv + 1, self_path);
	if (!strcmp(argv[1], "verify"))
		return cmd_verify(argc - 1, argv + 1, self_path);
	return loaders_usage();
}
